	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getHdrR())) ret.add(getHdrR());
		if(!MCCollectionUtil.contains(ret, getHdr4R())) ret.add(getHdr4R());
		if(!MCCollectionUtil.contains(ret, getDtlDispL())) ret.add(getDtlDispL());
		if(!MCCollectionUtil.contains(ret, getFixDtlL())) ret.add(getFixDtlL());
		if(!MCCollectionUtil.contains(ret, getDtlL())) ret.add(getDtlL());
		if(!MCCollectionUtil.contains(ret, getRefDtlDispL())) ret.add(getRefDtlDispL());
		if(!MCCollectionUtil.contains(ret, getRefDtlL())) ret.add(getRefDtlL());
		if(!MCCollectionUtil.contains(ret, getUsrDtlDispL())) ret.add(getUsrDtlDispL());
		if(!MCCollectionUtil.contains(ret, getUsrDtlL())) ret.add(getUsrDtlL());
		if(!MCCollectionUtil.contains(ret, getSprtAmtQtyCalDtlL())) ret.add(getSprtAmtQtyCalDtlL());
		if(!MCCollectionUtil.contains(ret, getCsvL())) ret.add(getCsvL());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getHdrR()) return "Hdr";
		if(aCnt == getHdr4R()) return "Hdr4";
		if(aCnt == getDtlDispL()) return "DtlDisp";
		if(aCnt == getFixDtlL()) return "FixDtl";
		if(aCnt == getDtlL()) return "Dtl";
		if(aCnt == getRefDtlDispL()) return "RefDtlDisp";
		if(aCnt == getRefDtlL()) return "RefDtl";
		if(aCnt == getUsrDtlDispL()) return "UsrDtlDisp";
		if(aCnt == getUsrDtlL()) return "UsrDtl";
		if(aCnt == getSprtAmtQtyCalDtlL()) return "SprtAmtQtyCalDtl";
		if(aCnt == getCsvL()) return "Csv";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("Hdr")) return getHdrR();
		if(bId.equals("Hdr4")) return getHdr4R();
		if(bId.equals("DtlDisp")) return getDtlDispL();
		if(bId.equals("FixDtl")) return getFixDtlL();
		if(bId.equals("Dtl")) return getDtlL();
		if(bId.equals("RefDtlDisp")) return getRefDtlDispL();
		if(bId.equals("RefDtl")) return getRefDtlL();
		if(bId.equals("UsrDtlDisp")) return getUsrDtlDispL();
		if(bId.equals("UsrDtl")) return getUsrDtlL();
		if(bId.equals("SprtAmtQtyCalDtl")) return getSprtAmtQtyCalDtlL();
		if(bId.equals("Csv")) return getCsvL();
		return super.getContainer(bId);
	}

